  "slug": "spinner",
  "name": "Spinner",
  "status": "experimental",
  "purpose": "Communicates that an operation is in progress without blocking the UI.",
  "scenarios": [
    "Show loading feedback while a form is submitted",
    "Indicate that a remote list is refreshing",
    "Reduce motion when the user prefers it"
  ],
  "props": {
    "size": {
      "type": "enum",
      "required": false,
      "description": "Visual size of the spinner.",
      "values": [
        "sm",
        "md",
        "lg"
      ],
      "default": "md"
    },
    "label": {
      "type": "string",
      "required": false,
      "description": "Accessible label describing the loading state.",
      "default": "Loading"
    }
  },
  "variants": [
    {
      "name": "size",
      "values": [
        "sm",
        "md",
        "lg"
      ],
      "default": "md",
      "description": "Visual size of the spinner."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Spinner is animated and announced."
    }
  ],
  "composition": {
    "allowedParents": [
      "button",
      "dialog",
      "app-shell",
      "page"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use as the only loading indicator for long operations without a status message.",
    "Do not disable reduced-motion preferences."
  ],
  "a11y": {
    "role": "status",
    "keyboard": [],
    "focus": "Spinner is not focusable; it is announced via aria-live.",
    "labeling": "An aria-label describes the loading state.",
    "wcag": [
      "4.1.3"
    ]
  },
  "responsive": {
    "strategy": "Size is token-based; animation respects reduced-motion preferences.",
    "breakpoints": {
      "compact": "Hit target remains at least the sm size.",
      "medium": "Default md size is used.",
      "large": "Default md size is used."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Rotation animation is direction-neutral.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "spinner",
    "states": [
      "sm",
      "md",
      "lg"
    ],
    "intents": [
      "indicate-busy"
    ]
  }
}

{
  "spinner": {
    "loading": "लोड हो रहा है",
    "saving": "सहेजा जा रहा है"
  }
}

{
  "spinner": {
    "loading": "لوڈ ہو رہا ہے",
    "saving": "محفوظ ہو رہا ہے"
  }
}

import './styles.css'

export type SpinnerSize = 'sm' | 'md' | 'lg'

export interface SpinnerProps {
  size?: SpinnerSize
  /** Accessible label describing the loading state. */
  label?: string
  className?: string
}

export function Spinner({ size = 'md', label = 'Loading', className }: SpinnerProps) {
  const classes = ['cu-spinner', `cu-spinner--${size}`, className].filter(Boolean).join(' ')

  return (
    <span
      className={classes}
      data-ai-role="spinner" data-ai-intent="indicate-busy"
      data-ai-state="loading"
      data-size={size}
      role="status"
      aria-live="polite"
      aria-label={label}
    >
      <svg aria-hidden="true" className="cu-spinner__svg" viewBox="0 0 24 24">
        <circle className="cu-spinner__track" cx="12" cy="12" r="10" />
        <circle className="cu-spinner__lead" cx="12" cy="12" r="10" />
      </svg>
    </span>
  )
}

.cu-spinner {
  display: inline-flex;
  inline-size: 1.5rem;
  block-size: 1.5rem;
  flex: none;
  color: var(--cu-color-palette-brand);
}

.cu-spinner--sm {
  inline-size: 1rem;
  block-size: 1rem;
}

.cu-spinner--lg {
  inline-size: 2rem;
  block-size: 2rem;
}

.cu-spinner__svg {
  inline-size: 100%;
  block-size: 100%;
  animation: cu-spin 1s linear infinite;
}

.cu-spinner__track,
.cu-spinner__lead {
  fill: none;
  stroke-width: 2.5;
}

.cu-spinner__track {
  stroke: color-mix(in srgb, var(--cu-color-palette-brand) 20%, transparent);
}

.cu-spinner__lead {
  stroke: currentColor;
  stroke-dasharray: 40 60;
  stroke-linecap: round;
}

@keyframes cu-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .cu-spinner__svg {
    animation-duration: 0.01ms;
  }
}
